def test_the_split_leaves_define_every_name_the_umbrella_used_to() -> None:
    """R7: the ten-second audit that would have caught the split's own defect first.

    `_REASON_WORDS, _REASON_CHARS = 2, 8` is a TUPLE assignment, and the splitter that carved
    `_hookmatch.py` into leaves handled only single-`Name` targets - so both constants vanished, five
    guard suites went red, and neither safeguard noticed: the leaves all PARSED (a name defined
    nowhere is a runtime error), and the 320-case equivalence check happened not to cover
    `reason_is_enough`, the one function that reads them.

    Behavior tests check the paths you thought of. A name census checks the ones you did not, and this
    one also keeps a future edit from moving a constant out of the module that uses it.
    """
    import ast

    def defined(path: pathlib.Path) -> set[str]:
        out: set[str] = set()
        for node in ast.parse(path.read_text()).body:
            if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                out.add(node.name)
            elif isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        out.add(target.id)
                    elif isinstance(target, ast.Tuple):
                        out.update(e.id for e in target.elts if isinstance(e, ast.Name))
        return out

    leaves = set().union(*(defined(SCRIPTS / f) for f in ("_hm_shape.py", "_hm_escape.py", "_hm_make.py")))
    # every name the leaves' own code references must be defined by one of them or imported
    for leaf in ("_hm_shape.py", "_hm_escape.py", "_hm_make.py"):
        tree = ast.parse((SCRIPTS / leaf).read_text())
        imported = {a.asname or a.name for n in ast.walk(tree) if isinstance(n, (ast.Import, ast.ImportFrom)) for a in n.names}
        used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
        local = defined(SCRIPTS / leaf) | imported
        # a name that is neither defined here, imported here, nor a builtin
        import builtins
        stray = {u for u in used - local if not hasattr(builtins, u) and u.isupper() or u.startswith("_") and u not in local}
        stray = {s for s in stray if s in leaves or s.startswith("_REASON") or s.isupper()}
        assert not stray, f"{leaf} uses names it does not define or import: {sorted(stray)}"
'''
p.write_text(t); print("the name census is now a test")
