"""Measure the two pages in headless Chromium: load, hit-test cost, hover cost per class, scroll frame time."""
import sys, time, json, statistics
from playwright.sync_api import sync_playwright

JS_FRAME = """() => new Promise(r => { const t0 = performance.now(); requestAnimationFrame(() => requestAnimationFrame(() => r(performance.now() - t0))); })"""

def run(path):
    out = {}
    with sync_playwright() as p:
        b = p.chromium.launch()
        pg = b.new_page(viewport={"width": 1400, "height": 1000})
        t0 = time.perf_counter()
        pg.goto("file://" + path, wait_until="load")
        out["load_s"] = round(time.perf_counter() - t0, 2)
        out["dom_nodes"] = pg.evaluate("() => document.getElementsByTagName('*').length")
        out["hit_elems"] = pg.evaluate("() => document.querySelectorAll('.hit, .hit *').length")
        # hit-test cost: elementFromPoint over a grid
        out["hit_grid_ms"] = pg.evaluate("""() => {
            const W = innerWidth, H = innerHeight; const times = []; const kinds = {};
            for (let x = 20; x < W; x += 50) for (let y = 20; y < H; y += 50) {
                const t = performance.now(); const el = document.elementFromPoint(x, y); const dt = performance.now() - t;
                const g = el && el.closest ? el.closest('g.f') : null; const k = g ? g.getAttribute('data-k') : '(none)';
                times.push(dt); (kinds[k] = kinds[k] || []).push(dt);
            }
            times.sort((a, b) => a - b);
            const per = {}; for (const k in kinds) { const v = kinds[k].sort((a,b)=>a-b); per[k] = [v.length, +v[Math.floor(v.length/2)].toFixed(2), +v[v.length-1].toFixed(2)]; }
            return { n: times.length, median: +times[Math.floor(times.length/2)].toFixed(2), p90: +times[Math.floor(times.length*0.9)].toFixed(2), max: +times[times.length-1].toFixed(2), total: +times.reduce((a,b)=>a+b,0).toFixed(0), per };
        }""")
        # real pointer moves: time a sweep of mouse.move across the viewport
        t0 = time.perf_counter()
        n = 0
        for y in range(50, 1000, 95):
            for x in range(50, 1400, 90):
                pg.mouse.move(x, y); n += 1
        out["mouse_sweep"] = {"moves": n, "ms_per_move": round((time.perf_counter() - t0) * 1000 / n, 1)}
        pg.mouse.move(0, 0)
        # hover cost per class: highlight(k) then two frames, then clear
        classes = pg.evaluate("() => window.l7rMap.classes")
        hover = {}
        for k in classes:
            pg.evaluate("k => window.l7rMap.highlight(k)", k)
            on = pg.evaluate(JS_FRAME)
            pg.evaluate("() => window.l7rMap.highlight(null)")
            off = pg.evaluate(JS_FRAME)
            hover[k] = (round(on), round(off))
        out["hover_ms_on_off"] = dict(sorted(hover.items(), key=lambda kv: -kv[1][0]))
        # scroll frames: wheel events, frame time
        pg.mouse.move(700, 500)
        fr = []
        for i in range(12):
            pg.mouse.wheel(0, 120)
            fr.append(pg.evaluate(JS_FRAME))
        out["scroll_frame_ms"] = {"median": round(statistics.median(fr)), "max": round(max(fr))}
        # zoom step
        pg.keyboard.press("+")
        out["zoom_in_frame_ms"] = round(pg.evaluate(JS_FRAME))
        fr = []
        for i in range(8):
            pg.mouse.wheel(0, 120)
            fr.append(pg.evaluate(JS_FRAME))
        out["scroll_frame_ms_zoomed"] = {"median": round(statistics.median(fr)), "max": round(max(fr))}
        out["hit_grid_ms_zoomed"] = pg.evaluate("""() => { const t = performance.now(); let n = 0; for (let x = 20; x < innerWidth; x += 50) for (let y = 20; y < innerHeight; y += 50) { document.elementFromPoint(x, y); n++; } return +((performance.now() - t)/n).toFixed(2); }""")
        b.close()
    return out

for path in sys.argv[1:]:
    print("=====", path)
    print(json.dumps(run(path), indent=1))
EOF
